command:
// Buccan Cook lets you make d4 more rations from any edible animal you kill. The
// system can't know when you've made a kill, so this is a button you press then.
// Delegates to the shared grants API (game.pirateborg.api.grants) so the roll/card
// and compendium-grant logic lives in one place.
const grants = game.pirateborg.api.grants;
const MEAT = "pirateborg.class-buccaneer;Exquisite smoked meat";
const plural = (n) => (n === 1 ? "" : "s");

const { total } = await grants.rollToCard(actor, {
  formula: "1d4",
  formulaLabel: "1d4 rations",
  title: "Cook rations",
  outcomeTitle: (n) => `+${Math.max(1, n)} ration${plural(Math.max(1, n))}`,
  description: (n) => `You butcher and smoke your kill, making ${Math.max(1, n)} ration${plural(Math.max(1, n))} of Exquisite smoked meat.`,
});

await grants.grantItem(actor, MEAT, { quantity: Math.max(1, total), stack: true });
